def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Count outcomes and behavior
    opp_c = 0
    my_d = 0
    for my, op in history:
        if op == 'C':
            opp_c += 1
        if my == 'D':
            my_d += 1
    opp_d = n - opp_c

    # Recent window (last 8)
    recent = history[-8:] if n >= 8 else history
    rec_opp_c = sum(1 for _, op in recent if op == 'C')
    rec_opp_d = len(recent) - rec_opp_c
    w = len(recent)

    # Last actions
    last_my, last_op = history[-1]

    # --- Endgame: exploit known cooperators, avoid being exploited ---
    remaining = 100 - n
    if remaining <= 2:
        if opp_d == 0 or (n >= 5 and rec_opp_d * 3 <= w):
            return 'D'
        if last_op == 'D':
            return 'D'
        if opp_c * 4 >= n * 3:
            return 'D'
        return 'C'

    if remaining <= 6:
        # Against high cooperators, defect. Against defectors, defect.
        if opp_d == 0 or opp_c * 4 >= n * 3:
            return 'D'
        if last_op == 'D':
            return 'D'
        if opp_d * 2 >= n:
            return 'D'
        return 'C'

    # --- Early game: cooperate but respond to early defection ---
    if n < 4:
        return 'C'

    # --- Detect near-always defector ---
    if opp_d >= n - 1 and n >= 5:
        return 'D'

    # --- Detect near-always cooperator: exploit, then reset ---
    if opp_d == 0:
        if n >= 60:
            # Late: exploit more; occasional cooperation to keep them nice.
            if n % 5 == 0:
                return 'C'
            return 'D'
        if n >= 20:
            # Moderate exploitation
            if n % 4 == 0:
                return 'C'
            return 'D'
        # Early probe, then return to cooperation
        if n % 7 == 0:
            return 'D'
        return 'C'

    # --- Mostly cooperative opponent ---
    if opp_c * 4 >= n * 3:
        # Occasional probe for extra payoff, but keep mostly cooperative
        if last_op == 'D':
            # They defected despite being mostly nice: forgive once
            if rec_opp_d <= 2:
                return 'C'
            return 'D'
        if n >= 12 and n % 9 == 0 and opp_d >= 1:
            return 'D'
        return 'C'

    # --- Mostly defecting opponent ---
    if opp_d * 3 >= n * 2:
        # Defect mostly, very rare probe
        if n % 13 == 0:
            return 'C'
        return 'D'

    # --- Mixed opponent: forgiving tit-for-tat with anti-spiral ---
    if last_op == 'D':
        # Retaliate, unless a sustained mutual defect spiral suggests forgiveness
        # Count consecutive opponent defections
        consec_op_d = 0
        for my, op in reversed(history):
            if op == 'D':
                consec_op_d += 1
            else:
                break
        consec_my_d = 0
        for my, op in reversed(history):
            if my == 'D':
                consec_my_d += 1
            else:
                break
        # If both stuck in defection for a while, try to break out
        if consec_op_d >= 3 and consec_my_d >= 2 and opp_c * 2 >= n:
            return 'C'
        # Forgive recent isolated defection if opponent generally cooperates
        if rec_opp_d <= 2 and rec_opp_c >= w - 2 and opp_c * 2 >= n:
            if rng.random() < 0.4:
                return 'C'
            return 'D'
        return 'D'

    # Opponent cooperated last
    if last_my == 'D' and last_op == 'C':
        # We got away with it; return to cooperation to keep them happy,
        # but against a forgiving opponent, occasionally press the advantage.
        if opp_c * 2 >= n and n % 6 == 0 and remaining > 15:
            return 'D'
        return 'C'

    # Default: cooperate
    return 'C'
